using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class TimelinePhysicsOperations
{
    public Settings pin_positions(RefCounted owner,string id,Settings state,Settings config,double time)
    {
        var pinned=new Settings();var target=animated_world(owner,id,time,true,new Settings());var prototype=Map(owner,"prototypes")[id].AsGodotDictionary();var graph=prototype["graph"].AsGodotDictionary();int type=config["type"].AsInt32();var points=state["points"].AsVector3Array();
        if(type==8)return _growth.pins(owner,id,time);
        if(type==5){if(config["rope_start"].AsBool())pinned[0]=attachment(owner,config["attachment"].AsString(),config["attachment_bone"].AsString(),config["pivot"].AsVector3(),time,target);if(config["rope_end"].AsBool())pinned[points.Length-1]=attachment(owner,config["end_actor"].AsString(),config["end_bone"].AsString(),config["end_offset"].AsVector3(),time,target*new Transform3D(Basis.Identity,new Vector3(0,-config["rope_length"].AsSingle(),0)));}
        else if(graph.Count>0){var vertices=graph["local"].AsVector3Array();var bounds=prototype["geometry"].AsGodotDictionary()["bounds"].AsAabb();int vertical=bounds.Size.Y>.0001?1:2;int region=config["pin_region"].AsInt32();for(int i=0;i<vertices.Length;i++){var point=vertices[i];if((region==1&&point[vertical]>=bounds.End[vertical]-bounds.Size[vertical]*.08)||(region==2&&point[vertical]<=bounds.Position[vertical]+bounds.Size[vertical]*.08)||(region==3&&point.X<=bounds.Position.X+bounds.Size.X*.08))pinned[i]=attachment(owner,config["attachment"].AsString(),config["attachment_bone"].AsString(),point,time,target);}}
        foreach(var value in config["pins"].AsGodotArray()){var pin=value.AsGodotDictionary();int index=Get(pin,"point",-1).AsInt32();if(index<0||index>=points.Length){warn(owner,prototype["actor"].As<Resource>().Get("display_name").AsString()+": pinned point "+index+" is outside this simulation mesh.");continue;}pinned[index]=Get(pin,"follow",true).AsBool()?attachment(owner,Get(pin,"actor","").AsString(),Get(pin,"bone","").AsString(),Get(pin,"offset",Vector3.Zero).AsVector3(),time,target):Get(pin,"world",points[index]);}return pinned;
    }
    public void particles(RefCounted owner,string id,Settings state,Settings config,double time,double h)
    {
        var points=state["points"].AsVector3Array();if(points.Length==0)return;int type=config["type"].AsInt32();if(type!=5&&type!=8)ensure_graph(owner,id,state,config);var prototype=Map(owner,"prototypes")[id].AsGodotDictionary();var graph=prototype["graph"].AsGodotDictionary();var previous=(Vector3[])points.Clone();var velocities=state["velocities"].AsVector3Array();var pinned=pin_positions(owner,id,state,config,time);float dt=(float)h;float mass=Math.Max(.001f,config["mass"].AsSingle());var acceleration=gravity(config)+config["wind"].AsVector3()/Math.Max(.01f,config["mass"].AsSingle());var impulses=events(config,local(owner,prototype["actor"].As<Resource>(),time),h);acceleration+=impulses["force"].AsVector3()/mass;var targets=type==8?_growth.targets(owner,id,time):new Settings();var wind=config["environment_wind"].AsVector3();float damping=(float)Math.Exp(-config["damping"].AsDouble()*h);
        for(int i=0;i<points.Length;i++){if(pinned.ContainsKey(i)){points[i]=pinned[i].AsVector3();continue;}velocities[i]+=impulses["impulse"].AsVector3()/mass;if(targets.ContainsKey(i))velocities[i]+=(targets[i].AsVector3()-points[i])*(config["mode"].AsInt32()==2?config["stiffness"].AsSingle()/mass:config["recovery"].AsSingle())*dt;var windAcceleration=wind.IsZeroApprox()?Vector3.Zero:(wind-velocities[i])*.12f;velocities[i]=(velocities[i]+(acceleration+windAcceleration)*dt)*damping;points[i]+=velocities[i]*dt;}
        if(type==1){var center=Vector3.Zero;var restCenter=Vector3.Zero;var rest=graph["rest"].AsVector3Array();foreach(var point in points)center+=point;foreach(var point in rest)restCenter+=point;center/=points.Length;restCenter/=points.Length;for(int i=0;i<points.Length;i++)if(!pinned.ContainsKey(i))points[i]=points[i].Lerp(center+rest[i]-restCenter,Math.Clamp(config["recovery"].AsSingle()*dt,0,.3f));}
        int iterations=Math.Clamp(config["iterations"].AsInt32(),1,24);var edges=graph["edges"].AsGodotArray();for(int iteration=0;iteration<iterations;iteration++){foreach(var value in edges){var edge=value.AsGodotArray();int a=edge[0].AsInt32(),b=edge[1].AsInt32();var difference=points[b]-points[a];float length=difference.Length();if(length<.000001)continue;double strength=config[edge[3].AsBool()?"bend":"stretch"].AsDouble();if(type==1)strength=1-Math.Pow(1-Math.Clamp(strength,0,1),1.0/iterations);float weight=pinned.ContainsKey(a)&&pinned.ContainsKey(b)?0:pinned.ContainsKey(a)||pinned.ContainsKey(b)?1:.5f;var correction=difference*((length-edge[2].AsSingle())/length)*(float)Math.Clamp(strength,0,1)*weight;if(!pinned.ContainsKey(a))points[a]+=correction;if(!pinned.ContainsKey(b))points[b]-=correction;}foreach(var index in pinned.Keys)points[index.AsInt32()]=pinned[index].AsVector3();}
        for(int i=0;i<points.Length;i++){var contacts=new GArray();if(config["collision"].AsBool()&&!pinned.ContainsKey(i)){var result=_collision.point_motion((RefCounted)Module(owner,"world"),id,previous[i],points[i],config["radius"].AsDouble(),config["layer"].AsInt32(),config["mask"].AsInt32(),new GArray{config["attachment"].AsString()});points[i]=result["position"].AsVector3();contacts=result["hits"].AsGodotArray();}velocities[i]=(points[i]-previous[i])/(float)Math.Max(.00001,h);foreach(var value in contacts){var normal=value.AsGodotDictionary()["normal"].AsVector3();float speed=velocities[i].Dot(normal);velocities[i]-=normal*Math.Min(speed,0);velocities[i]*=(float)Math.Exp(-Math.Max(0,config["friction"].AsDouble())*h*10);}}
        state["points"]=points;state["velocities"]=velocities;
    }
}
